catalog_script_client.script:
function onChange( control, oldValue, newValue, isLoading ) {
	console.info( "x_gamlp_idm_lc.On Identity Change Event( " + oldValue + "/" + newValue + " )" );
	if ( isLoading ) {
		console.info( "x_gamlp_idm_lc.On Identity Change Event - loading..." );
		return;
	}

	if ( g_form.getValue( "running_from" ) == "order_guide" && g_form.getValue( "entity_state" ) == "new" ) {
		console.info( "x_gamlp_idm_lc.On Entity Change Event - Order Guide New" );
		g_form.clearValue( "requested_offering" );
		g_form.setReadOnly( "requested_offering", false );
		return;
	}

	if ( newValue == '' ) {
		console.info( "x_gamlp_idm_lc.On Identity Change Event - newValue blank..." );
		g_form.clearValue( "initial_offering" );
		g_form.clearValue( "requested_offering" );
	} else if ( newValue && g_form.getValue( "business_service" ) ) {
		var _refreshIdentity = function( identity ) {
			console.info( "x_gamlp_idm_lc.On Identity Change Event._refreshIdentity( " + identity + " )" );

			var _refreshOfferingCallBack = function( response ) {
				var answer = response.responseXML.documentElement.getAttribute( "answer" );
				console.info( "x_gamlp_idm_lc.On Identity Change Event._refreshOfferingCallBack() - answer = " + answer );
				var result = JSON.parse( answer );

				if ( typeof result !== "undefined" && result.status.code == 0 ) {
					g_form.setValue( "initial_offering", result.userOfferings );
					g_form.setValue( "requested_offering", result.userOfferings );
				} else {
					console.warn( "x_gamlp_idm_lc.On Identity Change Event._refreshOfferingCallBack() - error -> " + result.status.message.message.toString() );
					g_form.clearValue( "requested_offering" );
					g_form.clearValue( "initial_offering" );
				}

				g_form.setReadOnly( "requested_offering", false );
				g_form.hideFieldMsg( "requested_offering", false );
				g_form.hideFieldMsg( "requested_offering_custom", false );
			};

			g_form.hideFieldMsg( "requested_offering", false );
			g_form.hideFieldMsg( "requested_offering_custom", false );
			// g_form.setReadOnly( "requested_offering", true );
			g_form.showFieldMsg( "requested_offering", getMessage( "x_gamlp_idm_lc.form.Refreshing" ), "info" );
			g_form.showFieldMsg( "requested_offering_custom", getMessage( "x_gamlp_idm_lc.form.Refreshing" ), "info" );

			var ajax = new GlideAjax( 'x_1610537_rbh_cust.ManageIdentityOfferingsForBusinessServiceUIHelper' );
			ajax.addParam( 'sysparm_name', 'getOffering' );
			ajax.addParam( 'sysparm_entity', g_form.getValue( "entity" ) );
			ajax.addParam( 'sysparm_identity', identity );
			ajax.addParam( "sysparm_business_service", g_form.getValue( "business_service" ) );
			ajax.getXML( _refreshOfferingCallBack );
		};

		_refreshIdentity( newValue );
	}

}
